{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Laninamivir octanoate, a lipophilic ester prodrug, has only 15% oral bioavailability in humans, below the 20% threshold; this is the closest low-F analog among the long-chain esterified drugs.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C12"],
      "claim": "DVAS, a long-chain alkyl ester of an amino acid-derived amide, has about 60% oral bioavailability in healthy volunteers; superficially supports high absorption but lacks the beta-lactone and formyl-leucine motif of the query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C29"],
      "claim": "Chloramphenicol palmitate, a long-chain fatty ester prodrug, is about 85% bioavailable in children; supports high absorption for fatty esters but is a prodrug of a small polar antibiotic, not a locally acting lipase inhibitor.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is recognized as orlistat, a locally acting gastrointestinal lipase inhibitor with negligible systemic absorption. Despite many lipophilic ester analogs showing high oral bioavailability, the beta-lactone/N-formyl-leucine structure and intended non-absorbable design support F <20%, so the prediction is low.",
  "evidence_gaps": [
    "No direct oral bioavailability measurement for orlistat is present in the provided evidence set.",
    "Most high-F analogs are systemically absorbed prodrugs or plasticizers and do not share the beta-lactone lipase-inhibitor mechanism.",
    "The only affirmative low-F analog, laninamivir octanoate, is structurally distant and provides moderate transferability at best."
  ],
  "new_evidence_assessment": [
    {
      "applicability": "moderate",
      "card_ids": ["C31"],
      "decision_effect": "strengthened",
      "direction": "supportive",
      "family": "lipophilic ester prodrugs"
    },
    {
      "applicability": "low",
      "card_ids": ["C12"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "amino acid ester drugs"
    },
    {
      "applicability": "low",
      "card_ids": ["C29"],
      "decision_effect": "no_change",
      "direction": "contradictory",
      "family": "fatty ester prodrugs"
    }
  ],
  "revision_action": "initial"
}

